using namespace port3ds;using namespace bwgame;
struct Point{int x,y;};
static std::vector<Point> flight(const UnitView* units,unsigned count,int width,int height,Point from,Point to){unsigned w=(width+63)/64,h=(height+63)/64;std::vector<int> costs(w*h,1),dist(w*h,1000000000),prev(w*h,-1);for(unsigned i=0;i<count;++i){const auto& u=units[i];if(!u.owner || u.owner>=8 || u.hp<=0)continue;unsigned range=0;switch(u.type){case 0:case 1:case 3:case 8:case 12:case 38:case 43:case 47:case 53:case 66:case 70:case 124:case 144:case 162:range=480;break;default:break;}if(!range)continue;for(unsigned y=0;y<h;++y)for(unsigned x=0;x<w;++x){auto dx=int(x*64+32)-u.x,dy=int(y*64+32)-u.y;auto d=dx*dx+dy*dy;if(d<int(range*range))costs[y*w+x]+=int((range*range-d)/1024)+40;}}auto cell=[&](Point p){return std::min(h-1,unsigned(p.y/64))*w+std::min(w-1,unsigned(p.x/64));};unsigned a=cell(from),b=cell(to);using Node=std::pair<int,unsigned>;std::priority_queue<Node,std::vector<Node>,std::greater<Node>> open;dist[a]=0;open.push({0,a});while(!open.empty()){auto at=open.top();open.pop();auto i=at.second;if(at.first!=dist[i])continue;if(i==b)break;int x=i%w,y=i/w;for(int dy=-1;dy<=1;++dy)for(int dx=-1;dx<=1;++dx){if(!dx && !dy)continue;int nx=x+dx,ny=y+dy;if(nx<0 || ny<0 || nx>=int(w) || ny>=int(h))continue;unsigned j=ny*w+nx;int d=at.first+costs[j]*(dx && dy?14:10);if(d<dist[j]){dist[j]=d;prev[j]=i;open.push({d,j});}}}assert(prev[b]>=0);std::vector<Point> route;for(int i=b;i!=int(a);i=prev[i])route.push_back({int((i%w)*64+32),int((i/w)*64+32)});std::reverse(route.begin(),route.end());std::vector<Point> turns;for(unsigned k=0;k<route.size();++k){if(k>0 && k+1<route.size()){auto a=route[k-1],b=route[k],c=route[k+1];if((b.x-a.x)*(c.y-b.y)==(b.y-a.y)*(c.x-b.x))continue;}turns.push_back(route[k]);}return turns;}

int main(int argc,char**argv){assert(argc==3);Engine e;assert(e.load(argv[1],argv[2],Scenario::terran_campaign_7));assert(e.start_recording("/tmp/sc3ds-terran08.journal"));e.set_fog_enabled(false);bool loaded=false,shield_requested=false,reshield=false;unsigned launched_at=0;unsigned stage=0;std::vector<Point> route;unsigned carrier=0;
for(unsigned frame=0;frame<60000 && e.snapshot().winner<0;++frame){if(!e.tick()){printf("RUNTIME ERROR frame%u %s\n",e.frame(),e.error());return 2;}SoundEvent sounds[256];e.drain_sounds(sounds,256);if(frame%24)continue;UnitView u[1700];auto n=e.visible_units(u,1700);UnitView* ship=nullptr;UnitView* emitter=nullptr;for(unsigned i=0;i<n;++i){if(u[i].owner==0 && u[i].type==11 && (!ship || u[i].cargo))ship=&u[i];if(u[i].type==217)emitter=&u[i];}
for(unsigned i=0;i<n;++i)if(u[i].owner==0 && u[i].type==7){auto& w=u[i];if(w.carried_powerup==217){carrier=e.own_unit_at(w.x,w.y);continue;}if(w.order==unsigned(Orders::PlayerGuard) || w.order==unsigned(Orders::Guard) || w.order==unsigned(Orders::Stop)){const UnitView* target=nullptr;int best=99999999;for(unsigned j=0;j<n;++j)if(u[j].mineral || (u[j].refinery && u[j].owner==0 && i%3==0)){int dx=u[j].x-w.x,dy=u[j].y-w.y,d=dx*dx+dy*dy;if(d<best){best=d;target=&u[j];}}if(target && e.select(w.x,w.y))e.command(Command::context,target->x,target->y);}}
for(unsigned i=0;i<n;++i)if(u[i].owner==0 && u[i].completed){auto& p=u[i];if(p.type==114 && e.count_units(0,11)<3 && e.select(p.x,p.y)){if(p.flying){if(p.order!=unsigned(Orders::BuildingLand)){bool ok=false;for(int y=1488;y<2320 && !ok;y+=64)for(int x=128;x<960 && !ok;x+=64)ok=e.perform(option_code(OptionKind::land),x,y);}}else if(p.x>900 || p.y<1400)e.perform(option_code(OptionKind::liftoff));else if(!e.perform(option_code(OptionKind::train,11)))e.perform(option_code(OptionKind::addon,115));}if(p.type==16 && frame%240==0 && e.select(p.x,p.y))e.move_selected(416,1840);}
UnitView* worker=nullptr;for(unsigned i=0;i<n;++i)if(u[i].type==7 && u[i].owner==0 && u[i].carried_powerup==217)worker=&u[i];
if(ship && !ship->cargo && !loaded && worker && e.select(ship->x,ship->y))e.perform(option_code(OptionKind::order,unsigned(Orders::PickupTransport)),worker->x,worker->y);
if(ship && ship->cargo && !loaded && e.count_units(0,11)>=3){bool gathered=true;for(unsigned i=0;i<n;++i)if(u[i].owner==0 && u[i].type==11){int dx=u[i].x-600,dy=u[i].y-1600;if(dx*dx+dy*dy>72*72){gathered=false;if(e.select(u[i].x,u[i].y))e.perform(option_code(OptionKind::order,unsigned(Orders::Move)),600,1600);}}if(!gathered)continue;bool shielded=false;for(unsigned j=0;j<n;++j)if(u[j].owner==0 && u[j].type==9){if(u[j].energy<150)shielded=true;else if(!shield_requested && e.select(u[j].x,u[j].y))shield_requested=e.perform(option_code(OptionKind::order,unsigned(Orders::CastDefensiveMatrix)),ship->x,ship->y);}if(!shielded)continue;launched_at=frame;assert(e.select_similar(ship->x,ship->y,400,1480)>=3);assert(e.store_group(0));loaded=true;route=flight(u,n,e.snapshot().width*32,e.snapshot().height*32,{ship->x,ship->y},{3632,1600});printf("Loaded emitter SCV frame%u route%zu\n",e.frame(),route.size());}
if(loaded && ship && e.recall_group(0)){if(ship->x>=3616 && ship->x<=3776 && ship->y>=1568 && ship->y<=1696){stage=route.size();e.perform(option_code(OptionKind::unload));}else if(stage<route.size()){auto p=route[stage];e.perform(option_code(OptionKind::order,unsigned(Orders::Move)),p.x,p.y);int dx=p.x-ship->x,dy=p.y-ship->y;if(dx*dx+dy*dy<80*80)++stage;}else{e.perform(option_code(OptionKind::unload));if(worker && e.select(worker->x,worker->y))e.move_selected(3632,1600);}}
if(ship){for(unsigned i=0;i<n;++i)if(u[i].owner==0 && u[i].type==9 && e.select(u[i].x,u[i].y)){if(loaded && frame>launched_at+800 && !reshield)reshield=e.perform(option_code(OptionKind::order,unsigned(Orders::CastDefensiveMatrix)),ship->x,ship->y);else if(!shield_requested || (u[i].energy<150 && !reshield))e.perform(option_code(OptionKind::order,unsigned(Orders::Move)),ship->x,ship->y);}if(frame%120==0)for(unsigned i=0;i<n;++i)if(u[i].owner==0 && u[i].type==8 && e.select(u[i].x,u[i].y)){if(loaded)e.command(Command::attack,ship->x,ship->y);else e.perform(option_code(OptionKind::order,unsigned(Orders::Move)),600,1600);}}
if(loaded && frame<12000 && frame%240==0){printf("flight f%u ship%d,%d hp%d cargo%u worker%d,%d hp%d\n",e.frame(),ship?ship->x:0,ship?ship->y:0,ship?ship->hp:0,ship?ship->cargo:0,worker?worker->x:0,worker?worker->y:0,worker?worker->hp:0);}
if(frame%2400==0){for(unsigned j=0;j<n;++j)if(u[j].owner==0 && (u[j].type==114 || u[j].type==115 || u[j].carried_powerup))printf("base unit%u %d,%d order%u\n",u[j].type,u[j].x,u[j].y,u[j].order);printf("TrumpCard f%u min%d gas%d carrier%u ship%u cargo%u stage%u\n",e.frame(),e.snapshot().minerals,e.snapshot().gas,carrier,e.count_units(0,11),ship?ship->cargo:0,stage);fflush(stdout);}}
printf("TrumpCard result%d frame%u\n",e.snapshot().winner,e.frame());assert(e.snapshot().winner==0 && loaded && shield_requested && e.count_units(0,16)==1);SaveView view;assert(e.save_game("/tmp/sc3ds-terran08-completed.sav",view));Engine replay;SaveView restored;assert(replay.load_save(argv[1],"/tmp/sc3ds-terran08-completed.sav","/tmp/sc3ds-terran08-replay","/tmp/sc3ds-terran08-map",restored));assert(e.state_digest()==replay.state_digest());puts("The Trump Card original victory, paid transport convoy, native Matrix, surviving Kerrigan and exact completed replay PASS");}
